// AbstractExperimentExecutionStepAO A step that is executed as part of an experiment.
//
// Example: [{"id":"40b0f797-912d-4256-8887-1553561962a9","ignoreFailure":false,"parameters":{"duration":"10s"},"predecessorId":null}]
type AbstractExperimentExecutionStepAO struct {
	// CustomLabel Custom label assigned during experiment design to express the intention of this step
	//
	// Example: Container 'xyz' can not be reached
	CustomLabel *string `json:"customLabel,omitempty"`

	// Ended Timestamp when this experiment step ended
	//
	// Example: 2023-01-01T09:00:00Z
	Ended *time.Time `json:"ended,omitempty"`

	// Id Unique identifier of this step execution
	//
	// Example: 40b0f797-912d-4256-8887-1553561962a9
	Id *openapi_types.UUID `json:"id,omitempty"`

	// IgnoreFailure Whether the experiment should fail/error immediately in case this step fails/errors.
	//
	// Example: false
	IgnoreFailure *bool `json:"ignoreFailure,omitempty"`

	// Parameters Step-specific parameters of the experiment step configuration
	//
	// Example: {"duration":"10s"}
	Parameters *map[string]interface{} `json:"parameters,omitempty"`

	// PredecessorId Unique identifier of the step execution that precedes this step, null if it is the first step of a lane
	//
	// Example: 40b0f797-912d-4256-8887-1553561962a9
	PredecessorId *openapi_types.UUID `json:"predecessorId,omitempty"`

	// Reason Reason in case this experiment step execution failed or errored
	//
	// Example: Couldn't read state of container...
	Reason *string `json:"reason,omitempty"`

	// Started Timestamp when this experiment step was started
	//
	// Example: 2023-01-01T09:00:00Z
	Started *time.Time `json:"started,omitempty"`

	// State Current state of this step in the experiment (e.g. RUNNING, FAILED, ERRORED, COMPLETED)
	//
	// Example: RUNNING
	State *string `json:"state,omitempty"`

	// StepType Type of this step execution (e.g. ACTION, WAIT)
	//
	// Example: ACTION
	StepType string `json:"stepType"`
	union    json.RawMessage
}

// AccessTokenPrincipalAL The logged event was performed via API authorized via access token
//
// Example: {"id":"VDKTEBLl","name":"CI/CD","principalType":"ACCESS_TOKEN","tokenType":"TEAM"}
type AccessTokenPrincipalAL struct {
	// Id Unique identifier of this access token principal
	//
	// Example: VDKTEBLl
	Id string `json:"id"`

	// Name Name of the access token that was used
	//
	// Example: CI/CD
	Name string `json:"name"`

	// PrincipalType Principal type for access token based principal
	//
	// Example: ACCESS_TOKEN
	PrincipalType AccessTokenPrincipalALPrincipalType `json:"principalType"`

	// TokenType Access token type that was used to perform the logged event
	//
	// Example: TEAM
	TokenType AccessTokenPrincipalALTokenType `json:"tokenType"`
}

// AccessTokenPrincipalALPrincipalType Principal type for access token based principal
//
// Example: ACCESS_TOKEN
type AccessTokenPrincipalALPrincipalType string

// AccessTokenPrincipalALTokenType Access token type that was used to perform the logged event
//
// Example: TEAM
type AccessTokenPrincipalALTokenType string

// AccessTokensPageItemAO A single access token of a team. The token itself can't be read again
//
// Example: {"id":"aP4cDVfA","name":"CI/CD"}
type AccessTokensPageItemAO struct {
	// Id Unique identifier of the access token
	//
	// Example: CQer2Oar
	Id *string `json:"id,omitempty"`

	// Name Name of the Access Token to document e.g. its purpose
	//
	// Example: CI/CD access token
	Name *string `json:"name,omitempty"`

	// Team Team associated with this token or null if this is an admin token
	//
	// Example: ADM
	Team *string `json:"team,omitempty"`

	// Type Type of the access token
	//
	// Example: ADMIN
	Type *AccessTokensPageItemAOType `json:"type,omitempty"`
}

// AccessTokensPageItemAOType Type of the access token
//
// Example: ADMIN
type AccessTokensPageItemAOType string

// AccessTokensPageItemV2AO A single access token
