// Example: {"environment":"Global","lanes":[{"steps":[{"actionType":"com.steadybit.extension_host.stress-cpu","ignoreFailure":false,"parameters":{"duration":"30s"},"radius":{"percentage":100,"predicate":{"operator":"AND","predicates":[{"key":"k8s.deployment","operator":"EQUALS","values":["hot-deals"]}]},"query":null,"targetType":"com.steadybit.extension_container.container"},"type":"action"}]}],"name":"Blackhole Hot-deals","properties":{"EXAMPLE_CUSTOM_PROPERTY":"I like this experiment!"},"team":"ADM"}
